Extend Aliases (line 27-32) with ["PhoneNumberPro"]="PhoneIntl", ["PhonePro"]="PhoneIntl" so the phone widget classifies consistently. Add new seed sets + members:

// Layout/structural + pure-presentational; never submit a value (backs IsNonDataField).
private static readonly HashSet<string> Structural = new(OIC){"Row","Column","FlexGrid","Section","Html","HtmlBlock","Heading","Divider","Image","Captcha"};
// Widgets rendering SQL/API/other-field data; submit no user value (superset of DisplayOnly).
private static readonly HashSet<string> ExternalDisplay = new(OIC){"DataRepeater","DynamicLabel","QRCode"};
// Value persists as a JSON blob (combined/structured/collection).
private static readonly HashSet<string> StructuredJson = new(OIC){"Composite","Address","FullName","Country","PhoneIntl","DataGrid","GridRepeater","File","PdfForm","Razor","PayPal","Stripe","Square","PaymentSummary"};
// Consent widgets: persist JSON audit trail AND project a bool.
private static readonly HashSet<string> Consent = new(OIC){"TermsPrivacy","Terms"};

public static bool IsStructural(string t)=>Structural.Contains(Canonicalize(t));
public static bool IsExternalDataDisplay(string t)=>ExternalDisplay.Contains(Canonicalize(t))||DisplayOnly.Contains(Canonicalize(t));
public static bool IsStructuredJson(string t)=>StructuredJson.Contains(Canonicalize(t));
public static bool IsConsentLike(string t)=>Consent.Contains(Canonicalize(t));
public static bool IsDataCarrying(string t){var c=Canonicalize(t);return !IsStructural(c)&&!IsExternalDataDisplay(c);}
public static SubmissionDataType CanonicalDataTypeFor(string type,bool hasOptions){/* body = ResolveDataType switch moved here, on Canonicalize(type).ToLowerInvariant(); checkbox branch uses hasOptions; returns String/LongText/Number/Date/Boolean/Json */}

Keep IsDisplayOnly for back-compat (or make it forward to IsExternalDataDisplay). Merge DisplayOnly into ExternalDisplay to avoid two overlapping sets.
